contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= withdrawAmount, "insufficient test balance");
        require(withdrawAmount <= address(c).balance, "withdraw exceeds c balance");

        uint cBalanceBefore = address(c).balance;
        uint ownerBalanceBefore = address(this).balance;

        c.withdraw(withdrawAmount); if (__ESBMC_reverted()) return;

        assert(address(c).balance == cBalanceBefore - withdrawAmount && address(this).balance == ownerBalanceBefore + withdrawAmount);
    }

    receive() external payable {}
}

