// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= withdrawAmount);
        vm.assume(withdrawAmount <= address(c).balance);
        uint cBalanceBefore = address(c).balance;
        uint ownerBalanceBefore = address(this).balance;
        try c.withdraw(withdrawAmount) {} catch { return; }
        assertTrue(address(c).balance == cBalanceBefore - withdrawAmount && address(this).balance == ownerBalanceBefore + withdrawAmount);
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
